package com.bank.discovery.registry;

import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;
import java.util.stream.Collectors;

// The registry: the live phone book of healthy instances per service name.
public class ServiceRegistry {
    private static final Logger log = Logger.getLogger(ServiceRegistry.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());
    }

    private final Map<String, List<ServiceInstance>> instances = new ConcurrentHashMap<>();
    private final long expiryMillis;

    public ServiceRegistry(long expiryMillis) { this.expiryMillis = expiryMillis; }

    // An instance registers itself when it starts.
    public void register(ServiceInstance instance) {
        instances.computeIfAbsent(instance.getServiceName(), k -> new CopyOnWriteArrayList<>())
                 .add(instance);
        log.info(() -> "REGISTERED " + instance.getServiceName() + " at " + instance.address());
    }

    public void heartbeat(ServiceInstance instance) { instance.heartbeat(); }

    // Return only instances that have heartbeat recently (healthy).
    public List<ServiceInstance> healthyInstances(String serviceName) {
        long now = System.currentTimeMillis();
        return instances.getOrDefault(serviceName, List.of()).stream()
                .filter(i -> now - i.getLastHeartbeat() <= expiryMillis)
                .collect(Collectors.toList());
    }

    // Prune dead instances (missed heartbeats) — runs periodically in production.
    public void evictStale() {
        long now = System.currentTimeMillis();
        instances.forEach((name, list) -> list.removeIf(i -> {
            boolean dead = now - i.getLastHeartbeat() > expiryMillis;
            if (dead) log.warning(() -> "EVICTED dead instance " + name + " at " + i.address());
            return dead;
        }));
    }
}
