package com.bank.discovery.client;

import com.bank.discovery.registry.ServiceInstance;
import com.bank.discovery.registry.ServiceRegistry;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;

// Client-side discovery: fetch healthy instances and pick one (round-robin).
public class DiscoveryClient {
    private static final Logger log = Logger.getLogger(DiscoveryClient.class.getName());
    private final ServiceRegistry registry;
    private final AtomicInteger counter = new AtomicInteger(0);

    public DiscoveryClient(ServiceRegistry registry) { this.registry = registry; }

    // Resolve logical name "payment-service" to one live address.
    public String resolve(String serviceName) {
        List<ServiceInstance> healthy = registry.healthyInstances(serviceName);
        if (healthy.isEmpty()) {
            throw new IllegalStateException("No healthy instances for " + serviceName);
        }
        int index = Math.abs(counter.getAndIncrement() % healthy.size());
        String address = healthy.get(index).address();
        log.info(() -> "DISCOVERY resolved " + serviceName + " -> " + address
                + " (" + healthy.size() + " healthy)");
        return address;
    }
}
