package com.bank.discovery.service;

import com.bank.discovery.client.DiscoveryClient;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class AccountService {
    private static final Logger log = Logger.getLogger(AccountService.class.getName());
    private final DiscoveryClient discovery;

    public AccountService(DiscoveryClient discovery) { this.discovery = discovery; }

    // Settle a transfer by discovering a payment instance at call time.
    public void transfer(String fromId, String toId, BigDecimal amount) {
        String paymentAddress = discovery.resolve("payment-service");
        // In production this would be an HTTP call: POST http://{paymentAddress}/api/v1/settle
        log.info(() -> "TRANSFER " + amount + " from " + fromId + " to " + toId
                + " via payment-service@" + paymentAddress + " SUCCESS");
    }
}
