package com.bank.discovery;

import com.bank.discovery.client.DiscoveryClient;
import com.bank.discovery.registry.ServiceInstance;
import com.bank.discovery.registry.ServiceRegistry;
import com.bank.discovery.service.AccountService;
import java.math.BigDecimal;
import java.util.logging.*;

public class DiscoveryDemo {
    public static void main(String[] args) {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) h.setFormatter(new BankLogFormatter());

        ServiceRegistry registry = new ServiceRegistry(5000); // 5s expiry for demo
        // Four payment instances register themselves.
        ServiceInstance p1 = new ServiceInstance("payment-service", "10.0.3.11", 8080);
        ServiceInstance p2 = new ServiceInstance("payment-service", "10.0.3.12", 8080);
        ServiceInstance p3 = new ServiceInstance("payment-service", "10.0.3.13", 8080);
        ServiceInstance p4 = new ServiceInstance("payment-service", "10.0.3.14", 8080);
        registry.register(p1); registry.register(p2);
        registry.register(p3); registry.register(p4);

        DiscoveryClient discovery = new DiscoveryClient(registry);
        AccountService accountService = new AccountService(discovery);

        // Several transfers show round-robin load balancing across 4 instances.
        for (int i = 0; i < 4; i++) {
            accountService.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        }

        // Simulate p3 crashing: it stops heartbeating. The others keep alive.
        Logger.getLogger(DiscoveryDemo.class.getName())
              .warning("Simulating crash of payment-service@10.0.3.13 (stops heartbeat)");
        for (ServiceInstance alive : new ServiceInstance[]{p1, p2, p4}) {
            alive.heartbeat();
        }
        try { Thread.sleep(6000); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        registry.evictStale(); // p3 pruned

        // New transfers route only to survivors.
        for (int i = 0; i < 3; i++) {
            accountService.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        }
    }
}

